package com.ssk.kiosk;import com.ssk.kiosk.dto.*;import com.ssk.kiosk.service.*;import com.ssk.kiosk.repo.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.*;import org.springframework.boot.test.context.*;import org.springframework.test.context.ActiveProfiles;import java.time.*;@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:test;MODE=MSSQLServer;DB_CLOSE_DELAY=-1","spring.flyway.enabled=false","spring.jpa.hibernate.ddl-auto=create-drop"}) class GatePassServiceTest{@Autowired GatePassService service;@Test void createsAndValidatesPass(){var r=new ApplicationRequest("Test User","VISITOR","PASSPORT","P123456","ACME","E1001","Meeting","HQ","G1",Instant.now().minusSeconds(60),Instant.now().plusSeconds(3600),"local://photo");var p=service.create(r);Assertions.assertTrue(service.validate(new ValidateRequest(p.qrToken())).valid());}}
